def execute(arguments):
    """
    数据格式转换

    参数:
        arguments (dict): 包含以下字段
            - data (any): 要转换的数据，必填
            - from_format (str): 源格式，"json"（默认）、"xml"、"yaml"
            - to_format (str): 目标格式，"json"（默认）、"xml"、"yaml"

    返回:
        dict: 包含转换结果的字典
            - success (bool): 是否成功
            - result (str): 转换后的数据
            - error (str): 错误信息（失败时）
    """
    import json

    data = arguments.get("data")
    from_format = arguments.get("from_format", "json")
    to_format = arguments.get("to_format", "json")

    if data is None:
        return {"success": False, "error": "请提供要转换的数据"}

    try:
        if from_format == "json":
            if isinstance(data, str):
                parsed_data = json.loads(data)
            else:
                parsed_data = data
        elif from_format == "xml":
            return {"success": False, "error": "XML解析需要xmltodict库支持"}
        elif from_format == "yaml":
            return {"success": False, "error": "YAML解析需要pyyaml库支持"}
        else:
            return {"success": False, "error": f"不支持的源格式: {from_format}"}

        if to_format == "json":
            result = json.dumps(parsed_data, ensure_ascii=False, indent=2)
        elif to_format == "xml":
            def dict_to_xml(data, root="root"):
                xml_parts = [f"<{root}>"]

                def to_xml(value, key):
                    if isinstance(value, dict):
                        xml_parts.append(f"<{key}>")
                        for k, v in value.items():
                            to_xml(v, k)
                        xml_parts.append(f"</{key}>")
                    elif isinstance(value, list):
                        for item in value:
                            to_xml(item, key)
                    else:
                        xml_parts.append(f"<{key}>{value}</{key}>")

                if isinstance(parsed_data, dict):
                    for k, v in parsed_data.items():
                        to_xml(v, k)
                else:
                    to_xml(parsed_data, "item")

                xml_parts.append(f"</{root}>")
                return "\n".join(xml_parts)

            result = dict_to_xml(parsed_data)
        elif to_format == "yaml":
            return {"success": False, "error": "YAML输出需要pyyaml库支持"}
        else:
            return {"success": False, "error": f"不支持的目标格式: {to_format}"}

        return {"success": True, "result": result}
    except json.JSONDecodeError as e:
        return {"success": False, "error": f"JSON解析失败: {str(e)}"}
    except Exception as e:
        return {"success": False, "error": f"转换失败: {str(e)}"}
